from pathlib import Path
path = Path('/src/libxml2/parser.c')
s = path.read_text()
start = s.find('xmlParseCommentComplex')
assert start != -1
# Find the specific terminator write within this function
needle = '\n    buf[len] = 0;'
pos = s.find(needle, start)
assert pos != -1
insert = """

    /*
     * Ensure there's always room for the terminating NUL.
     *
     * The in-loop growth check is based on a heuristic for COPY_BUF(), but the
     * loop can exit without triggering another growth step and leave len equal
     * to the allocated size. Writing buf[len] would then overflow by one.
     */
    if (len >= size) {
        xmlChar *new_buf;
        size_t new_size = size ? size * 2 : (len + 1);

        if (new_size <= len)
            new_size = len + 1;
        new_buf = (xmlChar *) xmlRealloc(buf, new_size);
        if (new_buf == NULL) {
            xmlFree(buf);
            xmlErrMemory(ctxt, NULL);
            return;
        }
        buf = new_buf;
        size = new_size;
    }
"""
# Avoid double-inserting if re-run
if insert.strip() in s[start:pos+len(needle)]:
    print('Patch already present')
else:
    s = s[:pos] + insert + s[pos:]
    path.write_text(s)
    print('Patched', path)
